        let (accepted, conflicts, errors) = studio_write(
            &job,
            PatchSet {
                updated_instances: vec![
                    PatchUpdate {
                        changed_parent: Some(app),
                        ..empty_update(local)
                    },
                    PatchUpdate {
                        changed_parent: Some(local),
                        ..empty_update(app)
                    },
                ],
                ..PatchSet::new()
            },
        );
        assert_eq!(accepted, PatchSet::new());
        assert_eq!(conflicts, PatchSet::new());
        assert_eq!(errors.len(), 2);
